INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 46, 'theory', 'Quiz: serde and errors');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 46, 0, 'Which serde attribute forbids unknown fields in a request''s JSON?', '["#[serde(strict)]", "#[serde(deny_unknown_fields)]", "#[serde(skip_unknown)]", "#[serde(no_extra)]"]', 1, 'deny_unknown_fields makes parsing strict: a typo in a field name becomes an error.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 46, 1, 'What status does the Json extractor return if the body is valid JSON but the fields do not match the types?', '["400", "415", "422", "500"]', 2, '422 Unprocessable Entity: the syntax is fine, but the data does not fit; 400 is a syntax error, 415 is the wrong Content-Type.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 46, 2, 'What must never be shown to the client in the response to an internal error?', '["A general message", "The request identifier", "The SQL query text, disk paths, and other details", "The status code"]', 2, 'Details go to the log; the client gets a general message and, possibly, the request identifier.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 46, 3, 'Why implement From<library_error> for AppError?', '["So that the ? operator converts errors on its own", "To speed up compilation", "To hide errors", "serde requires it"]', 0, '? calls From::from when the error types differ, which keeps the code linear.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 46, 4, 'How can you tell a missing field from an explicit null in a PATCH?', '["You can''t", "Option<Option<T>> with a suitable deserializer", "Use String", "Send two requests"]', 1, 'The outer Option means "the field was sent", the inner one means "a value or null".');
